/**
 *
 **/
Ext._define('adm.patrimonio.avaliacao.ItemGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'adm.patrimonio.avaliacao.ItemWindow',

    configOrderToolBar: ['addEx', 'editEx', 'removeEx', '-', 'undo', '-', 'search', '->', 'download'],

    statics: {
        rendererUnit: function(align, unit) {
            return function(value) {
                if(value)
                    return '<div style="display:block; text-align:' + align + '">' +
                            value + ' ' + unit +
                            '</div>';
                else
                    return '';
            };
        }
    },

    getAddExAction: function(cfg) {
        if(!this._addExAction)
            this._addExAction = Ext._create('Ext.Button', {
                text: 'Novo',
                iconCls: 'icon-core icon-core-add',
                scope: this,
                handler: this.createItem
            });

        return this._addExAction;
    },

    getEditExAction: function(cfg) {
        if(!this._editExAction)
            this._editExAction = Ext._create('Ext.Button', {
                text: 'Editar',
                iconCls: 'icon-core icon-core-edit',
                scope: this,
                handler: this.updateItem
            });

        return this._editExAction;
    },

    getRemoveExAction: function(cfg) {
        if(!this._removeExAction)
            this._removeExAction = Ext._create('Ext.Button', {
                text: 'Remover',
                iconCls: 'icon-core icon-core-delete',
                scope: this,
                handler: this.removeItems
            });

        return this._removeExAction;
    },

    setEvaluateType: function(evaluateType) {
        var evaluateTypeConfig = {
            1: [false, false, false, 'adm.patrimonio.avaliacao.ItemWindow'],
            2: [true, true, true, 'adm.patrimonio.avaliacao.ManualItemWindow'],
            3: [true, true, true, 'adm.patrimonio.avaliacao.RevaluateItemWindow'],
            4: [true, true, true, 'adm.patrimonio.avaliacao.ItemWindow'], // Definir Window própria para Reversão de Depreciação
        };
        var config = evaluateTypeConfig[evaluateType];

        this.getAddExAction().setDisabled(!config[0]);
        this.getEditExAction().setDisabled(!config[1]);
        this.getRemoveExAction().setDisabled(!config[2]);
        this.restWindow = config[3];
    },

    getUndoAction: function(cfg) {
        if(!this._undoAction)
            this._undoAction = Ext._create('Ext.Button', {
                text: 'Desfazer',
                scope: this,
                handler: this.undo
            });

        return this._undoAction;
    },

    _undoRequest: function(pkset, justify) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Desfazendo avaliação...'});

        mask.show();
        rest.doRequest(
            rest.getRoute('undo', false, 'POST', {
                scope: this,
                params: {
                    pkset: pkset,
                    justify: justify
                },
                callback: function() {
                    mask.hide();
                    mask = null;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success)
                        this.getStore().reload();
                    else
                        Ext.Msg.show({
                            title: 'Desfazendo',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function() {
                    Ext.Msg.show({
                        title: 'Desfazendo',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponivel no momento, tente novamente mais tarde.'
                    });
                }
            })
        );
    },

    undo: function() {
        var selected = this.getSelectionModel().getSelections();

        if(selected.length > 0) {
            Ext.Msg.prompt(
                'Justificativa',
                'Entre com a justificativa para o desfazimento da avaliação:',
                function(button, text) {
                    if(button != 'ok')
                        return;

                    this._undoRequest(
                        selected.map(function(data) { return data.get('pk'); }),
                        text
                    );
                },
                this
            );
        }
        else
            Ext.Msg.show({
                title: 'Desfazendo',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione as avaliações que deseja desfazer.'
            });
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {
                        header: '',
                        dataIndex: 'icons',
                        width: 105,
                        menuDisabled: true,
                        renderer: adm.daily.rendererIconGrid
                    },
                    {
                        header: 'Plaqueta',
                        dataIndex: 'plaqueta',
                        width: 75
                    },
                    {
                        header: 'Especie',
                        dataIndex: 'especie_unicode',
                        id: 'autoExpandColumn'
                    },
                    {
                        header: 'Custo',
                        dataIndex: 'custo_aquisicao',
                        width: 85,
                        renderer: toolkit.util.formatCurrency,
                        hidden: true,
                        sortable: true
                    },
                    {
                        header: 'Valor Atual',
                        dataIndex: 'valor_atual',
                        width: 85,
                        renderer: toolkit.util.formatCurrency,
                        sortable: true
                    },
                    {
                        header: 'Valor Liquido',
                        dataIndex: 'valor_avaliado',
                        width: 85,
                        renderer: toolkit.util.formatCurrency,
                        sortable: true
                    },
                    {
                        header: 'Residual',
                        dataIndex: 'residual',
                        width: 85,
                        renderer: toolkit.util.formatCurrency,
                        sortable: true
                    },
                    {
                        header: 'Variação',
                        dataIndex: 'depreciacao',
                        width: 85,
                        renderer: toolkit.util.formatCurrency,
                        sortable: true
                    },
                    {
                        header: 'Tombado',
                        dataIndex: 'data_tombo',
                        width: 75,
                        renderer: Ext.util.Format.dateRenderer('d/m/Y'),
                        hidden: true
                    },
                    {
                        header: 'Dias',
                        dataIndex: 'quantidade_dias',
                        width: 65,
                        renderer: adm.patrimonio.avaliacao.ItemGrid.rendererUnit('right', 'dia(s)'),
                        sortable: true
                    },
                    {
                        header: 'Nova vida util',
                        dataIndex: 'vida_util',
                        width: 115,
                        renderer: adm.patrimonio.avaliacao.ItemGrid.rendererUnit('right', 'ano(s)'),
                        sortable: true
                    },
                    {
                        header: 'Nova conservação',
                        dataIndex: 'conservacao_display',
                        width: 135
                    }
                ]
            );

        return this._columnModel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            viewConfig: {
                scope: this,
                getRowClass: function(record) {
                    css = [];

                    if(record.get('discarded'))
                        css.push('x-grid3-dashed');

                    return css.join(' ');
                }
            }
        });

        cfg.columnAction = false;

        adm.patrimonio.avaliacao.ItemGrid.superclass.constructor.call(this, cfg);
    }
});

/*
 * src: /app/root/adm/static/patrimonio/avaliacao/Manage.js
 */
/**
 *
 **/
Ext._define('adm.patrimonio.avaliacao.Manage', {
    extend: 'toolkit.widget.TabPanel',

    avaliacao: function(value, observe) {
        observe = (observe === undefined ? true : observe);

        if (value !== undefined) {
            this._avaliacaoGrid = value;

            if (observe)
                this.observeAvaliacao();
        }

        return this._avaliacaoGrid;
    },

    observeAvaliacao: function() {
        var value = this.avaliacao();

        if (value) {
            this.getItemAvaliacaoGrid().enable();
            this.getItemAvaliacaoGrid().setParam('avaliacao', value.get('pk'));
            this.getItemAvaliacaoGrid().setFilterProperty('avaliacao', value.get('pk'), 100);
            this.getItemAvaliacaoGrid().setEvaluateType(value.get('tipo'));
        } else {
            this.getItemAvaliacaoGrid().disable();
            this.getItemAvaliacaoGrid().getStore().removeAll();
        }
    },

    getAvaliacaoGrid: function() {
        if(!this._avaliacaoGrid) {
            this._avaliacaoGrid = Ext._create('adm.patrimonio.avaliacao.Grid', {
                region: 'north',
                height: 250,
                split: true
            });

            this._avaliacaoGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(selm) {
                    var selection = selm.getSelections();

                    if(selection.length > 0)
                        this.avaliacao(selection[0]);
                    else
                        this.avaliacao(null);
                }
            });
        }

        return this._avaliacaoGrid;
    },

    getItemAvaliacaoGrid: function() {
        if(!this._itemAvaliacaoGrid)
            this._itemAvaliacaoGrid = Ext._create('adm.patrimonio.avaliacao.ItemGrid', {
                region: 'center',
                minHeight: 300,
                gridAutoLoad: false,
                title: 'Itens da Avaliação'
            });

        return this._itemAvaliacaoGrid;
    },

    constructor: function(cfg) {
        cfg = cfg || {};

        Ext.applyIf(cfg, {
            title: 'Avaliação de Bens'
        });

            Ext.apply(
                cfg,
                {
                    border: false,
                    layout: 'border',
                    items: [
                        this.getItemAvaliacaoGrid(),
                        this.getAvaliacaoGrid()
                    ]
                }
            );

        adm.patrimonio.avaliacao.Manage.superclass.constructor.call(this, cfg);
        this.avaliacao(cfg.oId === undefined ? null : cfg.oId);
    },
});

/*
 * src: /app/root/adm/static/patrimonio/notification/Restful.js
 */
Ext._define('adm.patrimony.notification.Restful', {
    extend: 'core.Restful',
    resource: 'PATNotification',

    getFields: function(cfg) {
        if(!this._fields) {
            this._fields = adm.patrimony.notification.Restful.superclass.getFields.call(this, cfg).concat([
                {type: 'auto',   name: 'icons'},

                {type: "int",    name: "id", useNull: true},

                {type: "int",    name: "assets_movement", useNull: true},
                {type: "string", name: "assets_movement_unicode"},

                {type: "int",    name: "destination", useNull: true},
                {type: "string", name: "destination_unicode"},

                {type: "int",    name: "protocol", useNull: true},
                {type: "string", name: "protocol_unicode"},

                {type: "int",    name: "protocol_movement", useNull: true},
                {type: "string", name: "protocol_movement_unicode"},

                {type: "string", name: "content"},

                {type: "int",    name: "received_by", useNull: true},
                {type: "string", name: "received_by_unicode"},
                {type: "date",   name: "received_at", dateFormat: "d/m/Y H:i"},
                {type: "string", name: "received_at_formatted",
                    convert: function(v, data) {
                        if(data.received_at)
                            return data.received_at;
                        return '';
                    }
                },

                {type: "int",    name: "notified_by", useNull: true},
                {type: "string", name: "notified_by_unicode"},
                {type: "date",   name: "notified_at", dateFormat: "d/m/Y H:i"},

                {type: "int",    name: "created_by", useNull: true},
                {type: "string", name: "created_by_unicode"},
                {type: "date",   name: "created_at", dateFormat: "d/m/Y H:i"},

                {type: "int",    name: "modified_by", useNull: true},
                {type: "string", name: "modified_by_unicode"},
                {type: "date",   name: "modified_at", dateFormat: "d/m/Y H:i"},

                {type: "bool", name: "was_sent"},
            ]);
        }

        return this._fields;
    }
});

/*
 * src: /app/root/adm/static/patrimonio/notification/Window.js
 */
Ext._define('adm.patrimony.notification.Window', {
    extend: 'core.RestfulWindow',
    rest: 'adm.patrimony.notification.Restful',

    width: 900,

    doValidation: function() {
        var values = this.getFormPanel().getForm().getValues();

        if (!values.content)
            throw "Por favor, informe o conteúdo da notificação.";
    },

    save: function(close) {
        try {
            this.doValidation();
            adm.patrimony.notification.Window.superclass.save.call(this, close);
        } catch (e) {
            Ext.Msg.show({
                title: 'Validação',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: e
            });
        }
    },

    getDisplayFieldPanel: function () {
        if (this._displayPanel) {
            return this._displayPanel;
        }

        this._displayPanel = Ext._create('Ext.Panel', {
            layout: 'form',
            frame: true,
            defaults: {
                style: {
                    backgroundColor: '#ccd8e7',
                    border: '1px solid #99bbe8',
                    padding: '2px',
                    height: '15px'
                }
            },
            items: [
                {
                    xtype: 'displayfield',
                    fieldLabel: 'Destinatário',
                    name: 'destination_unicode'
                },
                {
                    xtype: 'displayfield',
                    fieldLabel: 'Protocolo',
                    name: 'protocol_unicode'
                },
            ]
        });

        return this._displayPanel;
    },

    getContentPanel: function () {
        if (this._contentPanel) {
            return this._contentPanel;
        }

        this._contentPanel = Ext._create('Ext.Panel', {
            layout: 'form',
            labelAlign: 'top',
            frame: true,
            items: [
                {
                    xtype: 'ckeditor',
                    fieldLabel: 'Conteúdo',
                    name: 'content',
                    height: 242,
                    startupFocus: true,
                }
            ]
        });

        return this._contentPanel;
    },

    getFormPanel: function () {
        if (!this._formPanel) {
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                frame: false,
                border: false,
                labelWidth: 85,
                items: [
                    this.getDisplayFieldPanel(),
                    this.getContentPanel(),
                ]
            });
        }
        return this._formPanel;
    }

});

/*
 * src: /app/root/adm/static/patrimonio/notification/Grid.js
 */
Ext._define('adm.patrimony.notification.Grid', {
    extend: 'core.RestfulGrid',
    restWindow: 'adm.patrimony.notification.Window',
    configOrderToolBar: ['add', 'edit', 'remove', 'send'],

    getColumnModel: function() {
        if(!this._columnModel) {
            this._columnModel = Ext._create('Ext.grid.ColumnModel', [
                Ext._create('Ext.grid.RowNumberer'),
                {
                    header: '',
                    dataIndex: 'icons',
                    width: 30,
                    menuDisabled: true,
                    renderer: adm.daily.rendererIconGrid
                },
                {
                    header: 'Chave',
                    dataIndex: 'id',
                    width: 50,
                    hidden: true
                },
                {
                    header: 'Destinatário',
                    dataIndex: 'destination_unicode',
                    id: 'autoExpandColumn'
                },
                {
                    header: 'Protocolo',
                    dataIndex: 'protocol_unicode',
                    width: 120,
                    sortable: true
                },
                {
                    header: 'Enviado',
                    dataIndex: 'was_sent',
                    width: 66,
                    renderer: function (value) {
                        return (value ? 'Sim' : 'Não');
                    }
                },
                {
                    header: 'Notificado por',
                    dataIndex: 'notified_by_unicode',
                    width: 180,
                    hidden: true
                },
                {
                    header: 'Notificado em',
                    dataIndex: 'notified_at',
                    width: 90,
                    renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'),
                    hidden: true
                },
                {
                    header: 'Recebido por',
                    dataIndex: 'received_by_unicode',
                    width: 180
                },
                {
                    header: 'Recebido em',
                    dataIndex: 'received_at',
                    width: 90,
                    renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')
                },
                {
                    header: 'Criado por',
                    dataIndex: 'created_by_unicode',
                    width: 120,
                    hidden: true
                },
                {
                    header: 'Criado em',
                    dataIndex: 'created_at',
                    width: 90,
                    renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'),
                    hidden: true
                },
                {
                    header: 'Modificado por',
                    dataIndex: 'modified_by_unicode',
                    width: 120,
                    hidden: true
                },
                {
                    header: 'Modificado em',
                    dataIndex: 'modified_at',
                    width: 90,
                    renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'),
                    hidden: true
                }
            ]);
        }

        return this._columnModel;
    },

    send: function(params) {
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Notificando...'});
        mask.show();

        Ext.Ajax.request({
            url: core.callAction('PATNotification', 'send'),
            scope: this,
            params: params,
            success: function(response, options) {
                var result = Ext.decode(response.responseText);

                if (result.success) {
                    this.getStore().reload();
                    return;
                }

                Ext.Msg.show({
                    title: 'Notificação',
                    msg: result.message,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            },
            failure: function(response, options) {
                Ext.Msg.show({
                    title: 'Notificação',
                    msg: 'Recurso indisponível no momento.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                });
            },
            callback: function(options, success, response) {
                mask.hide();
            },
        });
    },

    getSendAction: function() {
        if (this._sendAction) {
            return this._sendAction;
        }

        this._sendAction = Ext._create('Ext.Button', {
            text: 'Enviar',
            iconCls: 'icon-diarias icon-ocorrencia',
            scope: this,
            handler: function () {
                var selections = this.getSelectionModel().getSelections();

                if (!selections.length) {
                    Ext.Msg.show({
                        title: 'Notificação',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Selecione uma ou mais notificações para enviar.'
                    });
                    return;
                }

                var msg = 'Tem certeza de que deseja enviar esta notificação?';
                if (selections.length > 1) {
                    msg = 'Tem certeza de que deseja enviar estas notificações?';
                }

                Ext.Msg.show({
                    title: 'Notificação',
                    icon: Ext.Msg.QUESTION,
                    buttons: Ext.Msg.YESNO,
                    msg: msg,
                    scope: this,
                    minWidth: 250,
                    fn: function(btn) {
                        if (btn === 'no') {
                            return;
                        }
                        this.send({
                            pkset: selections.map(function(item) {
                                return item.get('pk');
                            })
                        });
                    }
                });
            }
        });

        return this._sendAction;
    },

    defaultValues: function(values) {
        if(values)
            this._defaultValues = values;

        return this._defaultValues;
    },

    createItem: function(values) {
        if(values instanceof Ext.Button)
            values = {};

        values = Ext.applyIf(
            core.nullValue(values, {}),
            this.defaultValues()
        );

        adm.patrimony.notification.Grid.superclass.createItem.call(this, values);
    },

    constructor: function(cfg) {
        cfg = cfg || {};
        Ext.applyIf(cfg, {
            columnAction: true
        });

        adm.patrimony.notification.Grid.superclass.constructor.call(this, cfg);
    }
});

